EXPECTED_COUNTS = {"customers": 100, "products": 50, "orders": 300, "order_items": 904}
TARGET = "default_data.default"

def convert(value, field):
    if value == "":
        if not field.nullable:
            raise ValueError(f"Missing required value: {field.name}")
        return None
    dtype = field.dataType
    if isinstance(dtype, DecimalType):
        return Decimal(value)
    if isinstance(dtype, IntegerType):
        return int(value)
    if isinstance(dtype, BooleanType):
        if value not in ("true", "false"):
            raise ValueError(f"Invalid boolean: {value}")
        return value == "true"
    if isinstance(dtype, DateType):
        return date.fromisoformat(value)
    if isinstance(dtype, TimestampType):
        return datetime.fromisoformat(value.replace("Z", "+00:00"))
    return value

# COMMAND ----------
# Alle Daten vor dem ersten Schreibvorgang prüfen.
spark.sql("USE SCHEMA default_data.default")
existing = [name for name in schemas if spark.catalog.tableExists(f"{TARGET}.{name}")]
if existing:
    raise RuntimeError(f"Import abgebrochen: Tabellen existieren bereits: {existing}")

tables = {}
for name, schema in schemas.items():
    reader = csv.DictReader(io.StringIO(CSV_DATA[name]))
    assert reader.fieldnames == schema.fieldNames(), f"Header mismatch: {name}"
    rows = [tuple(convert(row[field.name], field) for field in schema.fields) for row in reader]
    assert len(rows) == EXPECTED_COUNTS[name], f"Unexpected row count: {name}"
    tables[name] = spark.createDataFrame(rows, schema)

primary_keys = {"customers": "customer_id", "products": "product_id", "orders": "order_id", "order_items": "order_item_id"}
for name, key in primary_keys.items():
    assert tables[name].select(key).distinct().count() == EXPECTED_COUNTS[name], f"Duplicate key: {name}"
for child, parent, key in [("orders", "customers", "customer_id"), ("order_items", "orders", "order_id"), ("order_items", "products", "product_id")]:
    assert tables[child].join(tables[parent].select(key), key, "left_anti").count() == 0, f"Invalid foreign key: {child}.{key}"

# COMMAND ----------
# Neue verwaltete Delta-Tabellen erstellen. Bei Fehlern können bereits erstellte Tabellen bestehen bleiben.
for name, df in tables.items():
    target = f"{TARGET}.{name}"
    df.write.format("delta").mode("errorifexists").saveAsTable(target)
    saved = spark.table(target)
    assert saved.count() == EXPECTED_COUNTS[name], f"Row count mismatch after write: {target}"
    assert saved.exceptAll(df).count() == 0 and df.exceptAll(saved).count() == 0, f"Content mismatch: {target}"
    print(f"Erstellt und geprüft: {target} ({EXPECTED_COUNTS[name]} Zeilen)")

# COMMAND ----------
display(spark.sql("""
SELECT date_trunc('month', o.order_timestamp) AS month,
       p.category,
       ROUND(SUM(oi.line_total_eur), 2) AS revenue_eur
FROM default_data.default.orders o
JOIN default_data.default.order_items oi ON o.order_id = oi.order_id
JOIN default_data.default.products p ON oi.product_id = p.product_id
WHERE o.order_status NOT IN ('cancelled', 'returned')
GROUP BY 1, 2
ORDER BY 1, 2
"""))
